-- Generated by scripts/generate-codex-diagnostic-schema.mjs.
-- Run once per shard with bound backfillFrom/backfillTo; at most one day per invocation.
-- Repeatable, including overlaps with live MVs. Does not activate the read path.
SELECT throwIf({backfillTo:DateTime('UTC')} <= {backfillFrom:DateTime('UTC')}
  OR dateDiff('second', {backfillFrom:DateTime('UTC')}, {backfillTo:DateTime('UTC')}) > 86400,
  'Codex diagnostic backfill requires a positive interval of at most one day');

INSERT INTO claude_code.codex_diagnostic_events_v1 (UserEmail, Second, Model, ConversationId, Backend, ProjectName, AttributesJSON, MinTimestamp, MaxTimestamp, Identities)
WITH mapSort(ResourceAttributes) AS r, mapSort(LogAttributes) AS a
  SELECT coalesce(nullIf(r['user.email'], ''), nullIf(r['enduser.id'], ''), '') AS UserEmail,
  toStartOfSecond(Timestamp) AS Second, a['model'] AS Model,
  a['conversation.id'] AS ConversationId,
  multiIf(match(a['model'], '^(us|us-gov|eu|apac|jp|au|in|global)\\.'), 'bedrock-runtime',
    match(a['model'], '^[a-z][a-z0-9-]*[a-z]\\.'), 'bedrock-mantle',
    r['backend'] IN ('bedrock-mantle','bedrock-runtime'), r['backend'], 'unknown') AS Backend,
  r['project.name'] AS ProjectName,
  toJSONString(mapApply((k,v) -> (k, multiIf(has(['input_token_count','output_token_count','cached_token_count','cache_write_token_count','reasoning_token_count','tool_token_count'], k), 'present',
    k IN ('error','error.message'), if(v = '', '', 'present'), v)),
    mapFilter((k,v) -> has(['event.name','event.kind','duration_ms','attempt','http.response.status_code','error','error.message','success','tool_name','decision','source','startup.phase','input_token_count','output_token_count','cached_token_count','cache_write_token_count','reasoning_token_count','tool_token_count'], k), a))) AS AttributesJSON,
  min(Timestamp) AS MinTimestamp, max(Timestamp) AS MaxTimestamp,
  uniqExactState(tuple(toString(toTimeZone(Timestamp, 'UTC')), r, a)) AS Identities
  FROM claude_code.otel_logs
  WHERE startsWith(EventName, 'codex.')
    AND startsWith(a['event.name'], 'codex.') AND (Timestamp >= {backfillFrom:DateTime('UTC')} AND Timestamp < {backfillTo:DateTime('UTC')})
  GROUP BY UserEmail, Second, Model, ConversationId, Backend, ProjectName, AttributesJSON;
